-- PT122-S2-Q3. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT122-S2-Q3$batch09$ AND q.stimulus=$batch09$Most employees spend their time completing unimportant tasks for which they have been given firm schedules and deadlines. Efficient employees know how to ignore such demands and instead spend their time on projects that will yield big rewards for their employers if successful, even when such projects carry the risk of significant loss if unsuccessful.$batch09$ AND q.prompt=$batch09$Which one of the following is an example of efficiency as described above?$batch09$ AND q.correct_choice=$batch09$C$batch09$) THEN RAISE EXCEPTION 'Question changed: PT122-S2-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT122-S2-Q3$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S2-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT122-S2-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Rule$batch09$, $batch09$Efficient employees ignore unimportant tasks with firm schedules and deadlines. They spend that time on projects that could pay off big for the employer if successful, even when the projects are risky.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$Two halves. The employee sets aside an unimportant scheduled demand, and puts the time into something that could yield a big reward for the employer. Following a schedule isn't efficiency by this definition, and neither is skipping a deadline for more routine work.$batch09$), (2, $batch09$Goal$batch09$, $batch09$Skipping a routine scheduled obligation to pursue something with a big potential payoff for the employer.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT122-S2-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This is meeting a supervisor's deadline, which is the kind of demand efficient employees ignore.$batch09$), ($batch09$B$batch09$, $batch09$This is the trap, picked by 4%. It does ignore a deadline, so half the definition fits. But the time goes to routine correspondence that could wait, not a project with a big reward.$batch09$), ($batch09$C$batch09$, $batch09$Being on time for a monthly meeting is a routine scheduled demand. An urgent call from a major customer could mean a big reward for the employer. Skipping the first for the second is efficiency as the passage describes it.$batch09$), ($batch09$D$batch09$, $batch09$Daily meetings about workloads and schedules are scheduling, not a big-reward project.$batch09$), ($batch09$E$batch09$, $batch09$Scheduling tasks around the nearest deadlines is exactly what efficient employees ignore.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT122-S2-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
